1	using System.Globalization;
2	using System.Text.Json;
3	
4	namespace seed_b_backend.Api.Data;
5	
6	public static class SeedValueCanonicalizer
7	{
8	    public static string? Canonicalize(object? rawValue)
9	    {
10	        switch (rawValue)
11	        {
12	            case null:
13	                return null;
14	            case bool b:
15	                return b ? "true" : "false";
16	            case string s:
17	                return s;
18	            case double or float or decimal or int or long:
19	                return Convert.ToDouble(rawValue, CultureInfo.InvariantCulture)
20	                    .ToString(CultureInfo.InvariantCulture);
21	            case JsonElement element:
22	                return CanonicalizeJsonElement(element);
23	            default:
24	                return rawValue.ToString();
25	        }
26	    }
27	
28	    private static string? CanonicalizeJsonElement(JsonElement element)
29	    {
30	        return element.ValueKind switch
31	        {
32	            JsonValueKind.Null or JsonValueKind.Undefined => null,
33	            JsonValueKind.True => "true",
34	            JsonValueKind.False => "false",
35	            JsonValueKind.String => element.GetString(),
36	            JsonValueKind.Number => element.GetRawText(),
37	            _ => element.GetRawText(),
38	        };
39	    }
40	}
