 1	using System.Text.Json;
 2	using Microsoft.EntityFrameworkCore;
 3	using seed_b_backend.Api.Domain;
 4	
 5	namespace seed_b_backend.Api.Data;
 6	
 7	public static class SeedLoader
 8	{
 9	    private static readonly JsonSerializerOptions JsonOptions = new()
10	    {
11	        PropertyNameCaseInsensitive = false,
12	    };
13	
14	    public static async Task LoadAsync(AppDbContext context, string contentRootPath)
15	    {
16	        if (await context.Products.AnyAsync())
17	        {
18	            return;
19	        }
20	
21	        var path = Path.Combine(contentRootPath, "Data", "anfangsdatenbestand.json");
22	        var json = await File.ReadAllTextAsync(path);
23	        var root = JsonSerializer.Deserialize<SeedRoot>(json, JsonOptions)
24	                   ?? throw new InvalidOperationException("Anfangsdatenbestand konnte nicht gelesen werden.");
25	
26	        foreach (var seedCategory in root.Kategorien)
27	        {
28	            var category = new Category { Id = seedCategory.Id, Name = seedCategory.Name };
29	            context.Categories.Add(category);
30	
31	            foreach (var seedSubcategory in seedCategory.Unterkategorien)
32	            {
33	                var subcategory = new Subcategory
34	                {
35	                    Id = seedSubcategory.Id,
36	                    Name = seedSubcategory.Name,
37	                    CategoryId = category.Id,
38	                };
39	                context.Subcategories.Add(subcategory);
40	
41	                foreach (var propertyName in seedSubcategory.Eigenschaften)
42	                {
43	                    context.SubcategoryProperties.Add(new SubcategoryProperty
44	                    {
45	                        SubcategoryId = subcategory.Id,
46	                        Name = propertyName,
47	                    });
48	                }
49	            }
50	        }
51	
52	        foreach (var seedSupplier in root.Lieferanten)
53	        {
54	            context.Suppliers.Add(new Supplier { Id = seedSupplier.Id, Name = seedSupplier.Name });
55	        }
56	
57	        foreach (var seedProduct in root.Produkte)
58	        {
59	            var product = new Product
60	            {
61	                Id = seedProduct.Id,
62	                Name = seedProduct.Name,
63	                Description = seedProduct.Beschreibung,
64	                SubcategoryId = seedProduct.UnterkategorieId,
65	            };
66	            context.Products.Add(product);
67	
68	            foreach (var (propertyName, rawValue) in seedProduct.Eigenschaften)
69	            {
70	                var canonicalValue = SeedValueCanonicalizer.Canonicalize(rawValue);
71	                if (canonicalValue is null)
72	                {
73	                    continue;
74	                }
75	
76	                context.ProductPropertyValues.Add(new ProductPropertyValue
77	                {
78	                    ProductId = product.Id,
79	                    Name = propertyName,
80	                    Value = canonicalValue,
81	                });
82	            }
83	
84	            foreach (var seedOffer in seedProduct.Angebote)
85	            {
86	                context.Offers.Add(new Offer
87	                {
88	                    ProductId = product.Id,
89	                    SupplierId = seedOffer.LieferantId,
90	                    Price = seedOffer.Preis,
91	                });
92	            }
93	        }
94	
95	        await context.SaveChangesAsync();
96	    }
97	}

